// vectorFile mirrors testdata/devicejobs/vectors.json. The vectors were
// generated by an independent Python implementation of the contract, so this
// test is the Go half of the cross-language check.
type vectorFile struct {
	Contract string            `json:"contract"`
	Keys     map[string]string `json:"keys"`
	Keyrings map[string]struct {
		Current string `json:"current"`
		Next    string `json:"next"`
	} `json:"keyrings"`
	Signatures []struct {
		Name, Tag, Key, Payload, Sig string
	} `json:"signatures"`
	Envelopes []struct {
		Name, Tag, Keyring, Envelope, Expect, Payload string
	} `json:"envelopes"`
	PendingJobs []struct {
		Name        string   `json:"name"`
		Keyring     string   `json:"keyring"`
		ObjectKey   string   `json:"object_key"`
		AgentBucket string   `json:"agent_bucket"`
		Now         string   `json:"now"`
		Ledger      []string `json:"ledger"`
		Envelope    string   `json:"envelope"`
		Expect      string   `json:"expect"`
	} `json:"pending_jobs"`
}

func loadVectors(t *testing.T) *vectorFile {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "testdata", "devicejobs", "vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v vectorFile
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if v.Contract != "qc2-device-job-contract/2" {
		t.Fatalf("contract = %q", v.Contract)
	}
	return &v
}

func (v *vectorFile) keyring(t *testing.T, name string) *Keyring {
	t.Helper()
	kr, ok := v.Keyrings[name]
	if !ok {
		t.Fatalf("unknown keyring %q", name)
	}
	next := ""
	if kr.Next != "" {
		next = v.Keys[kr.Next]
	}
	k, err := NewKeyring(v.Keys[kr.Current], next)
	if err != nil {
		t.Fatal(err)
	}
	return k
}

func TestVectorKeyIDs(t *testing.T) {
	v := loadVectors(t)
	for _, pair := range [][2]string{{"current_hex", "current_kid"}, {"next_hex", "next_kid"}} {
		k, err := ParseKey(v.Keys[pair[0]])
		if err != nil {
			t.Fatal(err)
		}
		if got := KID(k); got != v.Keys[pair[1]] {
			t.Errorf("KID(%s) = %s, want %s", pair[0], got, v.Keys[pair[1]])
		}
	}
}

func TestVectorSignatures(t *testing.T) {
	v := loadVectors(t)
	for _, s := range v.Signatures {
		k, err := ParseKey(v.Keys[s.Key+"_hex"])
		if err != nil {
			t.Fatal(err)
		}
		if got := Sign(k, s.Tag, []byte(s.Payload)); got != s.Sig {
			t.Errorf("%s: sig = %s, want %s", s.Name, got, s.Sig)
		}
	}
}

func TestVectorEnvelopes(t *testing.T) {
	v := loadVectors(t)
	for _, e := range v.Envelopes {
		t.Run(e.Name, func(t *testing.T) {
			p, err := v.keyring(t, e.Keyring).Open(e.Tag, []byte(e.Envelope))
			if got := OutcomeOf(err); string(got) != e.Expect {
				t.Fatalf("outcome = %q (%v), want %q", got, err, e.Expect)
			}
			if err == nil && string(p) != e.Payload {
				t.Fatalf("payload = %q, want %q", p, e.Payload)
			}
		})
	}
}

func TestVectorPendingJobs(t *testing.T) {
	v := loadVectors(t)
	for _, c := range v.PendingJobs {
		t.Run(c.Name, func(t *testing.T) {
			now, err := ParseTime(c.Now)
			if err != nil {
				t.Fatal(err)
			}
			seen := func(id string) bool {
				for _, l := range c.Ledger {
					if l == id {
						return true
					}
				}
				return false
			}
			j, err := CheckPendingJob(v.keyring(t, c.Keyring), c.ObjectKey, c.AgentBucket, now, []byte(c.Envelope), seen)
			if got := OutcomeOf(err); string(got) != c.Expect {
				t.Fatalf("outcome = %q (%v), want %q", got, err, c.Expect)
			}
			if (c.Expect == "ok" || c.Expect == "expired") && j == nil {
				t.Fatal("want the parsed job back")
			}
		})
	}
}

// Seal output must open under the same tag, carry the current kid, and be
// accepted by a keyring that has the sealing key as NEXT (rotation).
func TestSealRoundTripAndRotation(t *testing.T) {
	v := loadVectors(t)
	cur := v.keyring(t, "current")
	payload := []byte(v.Signatures[2].Payload) // non-ASCII and '<'
	env, err := cur.Seal(TagJob, payload)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(env), `\u003c`) {
		t.Fatalf("expected Go's HTML-safe escaping in %s", env)
	}
	var e envelope
	if err := json.Unmarshal(env, &e); err != nil || e.Sig != v.Signatures[2].Sig || e.KID != v.Keys["current_kid"] {
		t.Fatalf("envelope %s does not match the vector (err %v)", env, err)
	}
	for _, ring := range []string{"current", "current+next", "next-as-current"} {
		if p, err := v.keyring(t, ring).Open(TagJob, env); err != nil || string(p) != string(payload) {
			t.Errorf("keyring %s: Open = %q, %v", ring, p, err)
		}
	}
	if _, err := cur.Open(TagResult, env); OutcomeOf(err) != OutcomeBadSignature {
		t.Errorf("cross-tag Open: %v", err)
	}
	if _, err := cur.Seal(TagJob, []byte("{not json")); err == nil {
		t.Error("Seal accepted invalid JSON")
	}
}

func TestParseKey(t *testing.T) {
	good := strings.Repeat("aB", 32)
	for _, s := range []string{good, "  " + good + "\n"} {
		if _, err := ParseKey(s); err != nil {
			t.Errorf("ParseKey(%q): %v", s, err)
		}
	}
	for _, s := range []string{"", good[:62], good + "00", good[:30] + " " + good[31:], "zz" + good[2:], strings.Repeat("0", 63) + "g"} {
		if _, err := ParseKey(s); err == nil {
			t.Errorf("ParseKey(%q) accepted", s)
		}
	}
	if _, err := NewKeyring(good, "short"); err == nil {
		t.Error("malformed DEVICE_JOB_KEY_NEXT accepted")
	}
	if _, err := NewKeyring("", good); err == nil {
		t.Error("NEXT without current accepted")
	}
}

func TestKeyringRedacts(t *testing.T) {
	key := strings.Repeat("ab", 32)
	kr, err := NewKeyring(key, "")
	if err != nil {
		t.Fatal(err)
	}
	for _, s := range []string{
		kr.String(), kr.GoString(),
	} {
		if strings.Contains(s, key[:16]) {
			t.Errorf("keyring printed key material: %s", s)
		}
	}
}

func TestCheckPendingJobSizeAndUTF8(t *testing.T) {
	v := loadVectors(t)
	kr := v.keyring(t, "current")
	now := time.Date(2026, 11, 5, 12, 5, 0, 0, time.UTC)
	key := "jobs/pending/6f1c2e1a-3b7d-4c55-9a0e-2f4b8d9c1e01.json"
	big := make([]byte, MaxJobBytes+1)
	if _, err := CheckPendingJob(kr, key, "qc2-device-jobs-test", now, big, nil); OutcomeOf(err) != OutcomeTooLarge {
		t.Errorf("oversized: %v", err)
	}
	if _, err := CheckPendingJob(kr, key, "qc2-device-jobs-test", now, []byte("{\"v\":1,\xff}"), nil); OutcomeOf(err) != OutcomeBadEnvelope {
		t.Errorf("invalid UTF-8: %v", err)
	}
	// Just under the cap, all '[': must be rejected without deep recursion
	// (the security review measured ~256 MB of stack before the depth limit).
	deep := bytes.Repeat([]byte("["), MaxJobBytes)
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	if _, err := CheckPendingJob(kr, key, "qc2-device-jobs-test", now, deep, nil); OutcomeOf(err) != OutcomeBadEnvelope {
		t.Errorf("deep nesting: %v", err)
	}
	runtime.ReadMemStats(&after)
	if grew := int64(after.StackSys) - int64(before.StackSys); grew > 8<<20 {
		t.Errorf("stack grew by %d bytes on a deeply nested object", grew)
	}
}

func TestHasLoneSurrogate(t *testing.T) {
	cases := map[string]bool{
		`"plain"`:                    false,
		`"\ud83c\udfb8 guitar"`:      false,
		`"\ud800"`:                   true,
		`"\udfb8"`:                   true,
		`"\ud83c x"`:                 true,
		`"\\ud800"`:                  false, // escaped backslash, not an escape
		`"\ud83c\u0041"`:             true,
		`"tail \ud83c"`:              true,
		`"\u00e9\u003c\ud83c\udfb8"`: false,
	}
	for lit, want := range cases {
		if got := hasLoneSurrogate([]byte(lit)); got != want {
			t.Errorf("hasLoneSurrogate(%s) = %v, want %v", lit, got, want)
		}
	}
}

// A NEXT key identical to the current one is ignored; a different key that
// shares the current kid (forced here, since a real 32-bit collision can't be
// constructed in a test) is refused.
func TestNextKeyKIDCollision(t *testing.T) {
	cur := strings.Repeat("ab", 32)
	kr, err := NewKeyring(cur, cur)
	if err != nil || kr.next != nil {
		t.Fatalf("identical NEXT: %v, next set=%v", err, kr != nil && kr.next != nil)
	}
	other, _ := ParseKey(strings.Repeat("cd", 32))
	kr.cur.kid = KID(other) // simulate the collision
	if err := kr.setNext(other); err == nil || !strings.Contains(err.Error(), "collides") {
		t.Fatalf("colliding NEXT accepted: %v", err)
	}
}

// Contract v2 only appended vectors: the 82 v1 entries (4 signatures, 21 envelopes and the first 57
// pending jobs) are byte for byte what they were in qc2-device-job-contract/1. The digest is over
// each entry's raw JSON text, as gen_vectors.py writes it, in file order.
func TestV1VectorsUnchanged(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "testdata", "devicejobs", "vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	var sigs, envs, pend []json.RawMessage
	for k, dst := range map[string]*[]json.RawMessage{"signatures": &sigs, "envelopes": &envs, "pending_jobs": &pend} {
		if err := json.Unmarshal(m[k], dst); err != nil {
			t.Fatal(err)
		}
	}
	if len(sigs) != 4 || len(envs) != 21 || len(pend) < 57 {
		t.Fatalf("v1 sections changed size: %d %d %d", len(sigs), len(envs), len(pend))
	}
	h := sha256.New()
	for _, sec := range [][]json.RawMessage{sigs, envs, pend[:57]} {
		for _, e := range sec {
			h.Write(e)
			h.Write([]byte{0})
		}
	}
	const want = "e877ca5c1d4277a342f29fcea464aceec0a101d1ebf3f561ff56bbe6631dc9ba"
	if got := hex.EncodeToString(h.Sum(nil)); got != want {
		t.Fatalf("a v1 vector changed (digest %s): that is a contract change for v1 kinds", got)
	}
}
